// Gate (e): the on-chain 7-card evaluator (contracts/src/Eval7.runar.ts, generated by contracts/gen/gen-eval7.py)
// must agree with the Go evaluator (internal/game/eval) on every hand in the shared corpus. At showdown the
// dispute referee runs this evaluator, so a disagreement is a wrong payout.
//
// Every evaluation is a real @bsv/sdk `Spend` of the compiled script: MockProvider replays each input through the
// interpreter. The vectors come from packages/protocol/test/fixtures/eval-vectors.json (Go-scored); `bestScore`
// (packages/protocol/src/eval.ts) is the TypeScript reference that test/eval.test.ts holds to the same Go scores.
import { describe, it, expect, beforeAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { RunarContract, MockProvider, LocalSigner, buildP2PKHScript } from 'runar-sdk';
import type { RunarArtifact } from 'runar-ir-schema';
import { bestScore } from '@brc100-poker/protocol';
import { contractsRoot, loadArtifact } from './helpers';

interface Vector { cards: number[]; category: number; score: number; }
const vectors: Vector[] = JSON.parse(
  readFileSync(
    join(contractsRoot, '..', 'packages', 'protocol', 'test', 'fixtures', 'eval-vectors.json'), 'utf8'),
);

const REJECTED = /input 0: Script evaluation error/;
let artifact: RunarArtifact;
let scriptBytes = 0;

/** Deploys the evaluator and spends it with `check(cards..., claimed)`. Resolves if Spend accepts. */
async function spend(cards: number[], claimed: number): Promise<void> {
  const provider = new MockProvider('testnet');
  const signer = new LocalSigner('ee'.repeat(32));
  provider.addUtxo(await signer.getAddress(), {
    txid: 'ee'.repeat(32), outputIndex: 0, satoshis: 1_000_000,
    script: buildP2PKHScript(await signer.getPublicKey()),
  });
  const contract = new RunarContract(artifact, []);
  await contract.deploy(provider, signer, { satoshis: 1000 });
  await contract.call('check', [...cards.map(BigInt), BigInt(claimed)], provider, signer, {});
}

beforeAll(() => {
  execFileSync('node', [join(contractsRoot, 'compile.mjs'), 'Eval7'], { stdio: 'pipe' });
  artifact = loadArtifact('Eval7');
  scriptBytes = artifact.script.length / 2;
});

describe('gate e', () => {
  it('the compiled evaluator accepts bestScore for every vector', async () => {
    const started = Date.now();
    let first: string | undefined;
    for (const v of vectors) {
      try {
        await spend(v.cards, bestScore(v.cards));
      } catch (e) {
        first = `${v.cards.join(',')} (Go category ${v.category}, score ${v.score}, bestScore ${bestScore(v.cards)}): ${(e as Error).message}`;
        break;
      }
    }
    console.log(`gate e: ${vectors.length} vectors, script ${scriptBytes} bytes, ${((Date.now() - started) / 1000).toFixed(1)} s`);
    expect(first, 'first failing hand').toBeUndefined();
  }, 3_600_000);

  it('rejects bestScore - 1 and bestScore + 1 for one vector per category', async () => {
    const seen = new Set<number>();
    for (const v of vectors) {
      if (seen.has(v.category)) continue;
      seen.add(v.category);
      const good = bestScore(v.cards);
      await expect(spend(v.cards, good - 1), `category ${v.category}, -1`).rejects.toThrow(REJECTED);
      await expect(spend(v.cards, good + 1), `category ${v.category}, +1`).rejects.toThrow(REJECTED);
    }
    expect([...seen].sort()).toEqual([0, 1, 2, 3, 4, 5, 6, 7, 8]);
  }, 600_000);

  it('rejects a card index out of range', async () => {
    const good = vectors[0];
    await expect(spend([52, ...good.cards.slice(1)], bestScore(good.cards))).rejects.toThrow(REJECTED);
    await expect(spend([-1, ...good.cards.slice(1)], bestScore(good.cards))).rejects.toThrow(REJECTED);
  }, 120_000);
});
